{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "AST-004, a high-transfer adenosine analogue, achieved brain/plasma ratios of 10–30% in vivo, demonstrating meaningful brain distribution despite polar nucleoside features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Radiolabeled SIBA showed persistent brain radioactivity after IV dosing in rats, directly demonstrating BBB crossing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "PRE-084 reached 773.6 ng/g in mouse brain at Tmax with rapid CNS distribution, supporting good brain access for a small heterocyclic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "A closely transferable aminotriazine analogue with a basic amine substituent had a brain-to-serum AUC ratio of 2.69 in rats, indicating good BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Nelarabine metabolite ara-G showed excellent CSF penetration in non-human primate pharmacokinetic studies, supporting CNS access for heteroaromatic amine nucleoside-like scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Lorlatinib, a CNS-penetrant kinase inhibitor, had an average human CSF/plasma ratio of 0.75, demonstrating high BBB permeability in a relevant oncology context.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "DAPPD was detected in plasma, CSF, and brain after systemic administration in mice, directly confirming BBB crossing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Moclobemide achieved a CSF/plasma ratio of 0.5 in humans, showing good brain penetration for a small molecule with an amide and morpholine-like moiety.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "PhIP crossed the BBB after systemic administration, providing additional evidence that heteroaromatic amines can achieve CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues demonstrate meaningful BBB/CNS penetration across diverse chemotypes, including direct brain/plasma, CSF, and brain-uptake measurements; the query's CNS-permeable features align with these results, supporting a pass for meaningful CNS access.",
  "evidence_gaps": [
    "No direct query-specific brain/plasma or CSF measurement is provided; prediction relies on high-transfer analogues.",
    "No explicit P-gp/BCRP efflux data for the query are shown, though the overall positive in vivo evidence outweighs this uncertainty.",
    "The brain tumor/glioma condition may alter BBB integrity; most evidence is from normal animals or non-tumor patients."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

